", \"data-ga\": \"vis\", \"aria-label\": \"public\", checked: on, disabled: busy });\n  box.addEventListener(\"change\", function () {\n    if (on) { G.confirm = it.id; G.confirmAct = \"private\"; renderGrid(); }\n    else setVisibility(it, true);\n  });\n  return h(\"label\", { class: \"sw\" }, box, h(\"span\", { text: \"public\" }));\n}\nasync function setVisibility(it, makePublic) {\n  G.busy[it.id] = true; renderGrid();\n  try {\n    var r = ok(await libPost(\"/api/library/items/\" + it.id + (makePublic ? \"/publish\" : \"/private\")));\n    delete G.busy[it.id];\n    var next = r.item;\n    G.items = G.items.map(function (i) { return i.id === it.id && next ? Object.assign({}, i, next) : i; });\n    // under the public/private chips a file that just switched no longer belongs\n    if ((G.filter === \"public\" || G.filter === \"private\") && next && next.visibility !== G.filter) {\n      G.items = G.items.filter(function (i) { return i.id !== it.id; });\n    }\n    renderGrid(); reloadUsage();\n    if (makePublic && next && next.url) toast(\"public: link ready\", { href: next.url, label: \"open\" });\n    else toast(makePublic ? \"public\" : \"private\");\n  } catch (e) { delete G.busy[it.id]; renderGrid(); toast(describe(e).text); }\n}\nfunction privateToStudio(it) {\n  G.busy[it.id] = true; renderGrid();\n  openTabFor(async function () {\n    return ok(await libPost(\"/api/library/items/\" + it.id + \"/studio\")).url;\n  }).then(function () { delete G.busy[it.id]; renderGrid(); refreshGrid(); }, function (e) { delete G.busy[it.id]; renderGrid(); toast(describe(e).text); });\n}\n\nsetPane(\"link\");\nrefreshGrid();\n</script>\n</body>\n</html>\n";
